export function groupTipsByDate(tips: EmployeeTip[]): Map<string, EmployeeTip[]> {
  const grouped = new Map<string, EmployeeTip[]>();

  tips.forEach(tip => {
    const date = tip.recorded_at.split('T')[0]; // Get YYYY-MM-DD
    if (!grouped.has(date)) {
      grouped.set(date, []);
    }
    grouped.get(date)!.push(tip);
  });

  return grouped;
}
```

</details>

